// Fraunces Bold and Manrope Bold (latin subset, woff) embedded as base64 for
// the link-preview card (app/api/og/route.tsx). Embedded rather than read from
// disk or fetched: the production image is a traced standalone build where
// arbitrary files aren't guaranteed to exist, and the card must never depend
// on a network call. Both fonts are SIL OFL, via @fontsource.
const FRAUNCES_700 = "";
const MANROPE_700 = "";

const toArrayBuffer = (b64: string): ArrayBuffer => {
  const buf = Buffer.from(b64, "base64");
  return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer;
};

export const ogFonts = () => [
  { name: "Fraunces", data: toArrayBuffer(FRAUNCES_700), weight: 700 as const, style: "normal" as const },
  { name: "Manrope", data: toArrayBuffer(MANROPE_700), weight: 700 as const, style: "normal" as const },
];
